const body = $json.body ?? $json;

// FE contract v1.0 fields
const message = String(body.message ?? body.chatInput ?? body.text ?? '').trim();
const sessionId = String(body.sessionId ?? body.metadata?.userId ?? body.metadata?.userEmail ?? 'guest');

const metadata = {
  userId: body.metadata?.userId,
  userEmail: body.metadata?.userEmail,
  token: body.metadata?.token,
  screeningId: body.metadata?.screeningId,
  riskLevel: body.metadata?.riskLevel,
};

const consultationContext = body.context?.consultationContext ?? null;

return [
  {
    json: {
      // Keep both legacy + agent-friendly fields
      message,
      chatInput: message,
      text: message,
      sessionId,
      locale: body.locale ?? 'vi-VN',
      source: body.source ?? 'patient-review-page',
      timestamp: body.timestamp ?? new Date().toISOString(),
      metadata,
      context: {
        consultationContext,
      },
      traceId: body.traceId ?? $execution.id,
    },
  },
];

function safeJsonParse(text) {
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

const traceId = $json.traceId ?? $execution.id;

// Agent node often outputs a string in one of these fields.
const raw =
  $json.output ??
  $json.text ??
  $json.answer ??
  $json.response ??
  $json.result ??
  '';

const asString = typeof raw === 'string' ? raw : JSON.stringify(raw);
const parsed = typeof raw === 'object' && raw != null ? raw : safeJsonParse(asString);

const reply =
  (parsed && typeof parsed.reply === 'string' && parsed.reply.trim()) ||
  (typeof raw === 'string' && raw.trim()) ||
  'Mình đã nhận yêu cầu. Bạn cho phép mình tìm lịch phù hợp và gợi ý phương án đặt lịch nhé?';

return [
  {
    json: {
      reply,
      intent: parsed?.intent ?? 'UNKNOWN',
      requiresConfirmation: Boolean(parsed?.requiresConfirmation),
      suggestedSlots: Array.isArray(parsed?.suggestedSlots)
        ? parsed.suggestedSlots
        : [],
      action: parsed?.action ?? { type: 'NONE' },
      traceId: parsed?.traceId ?? traceId,
    },
  },
];
